const allInputs = $input.all();
const emailDetails = $('Get Email Details').all();

return allInputs.map((inputItem, index) => {
  const input = inputItem.json;
  let raw = input.output || input.text || input.content || '';

  raw = String(raw)
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();

  const match = raw.match(/\{[\s\S]*\}/);
  const jsonString = match ? match[0] : raw;

  let tx = {};
  try {
    tx = JSON.parse(jsonString);
  } catch (e) {
    tx = { is_financial: false };
  }

  const emailData = emailDetails[index]?.json || {};
  const emailId = String(emailData.id || emailData.threadId || `em_${index}`);

  let date = String(tx.Date || new Date().toISOString().slice(0, 10)).trim();
  if (date.startsWith('2023') || date.startsWith('2024') || date.startsWith('2025') || date.includes('Thu') || date.includes('Wed') || date.length < 10) {
    date = new Date().toISOString().slice(0, 10);
  }
  const month = date.slice(0, 7);

  let type = 'expense';
  const rawType = String(tx.Type || 'expense').toLowerCase().trim();
  if (['income', 'credit', 'salary', 'deposit'].some(k => rawType.includes(k))) {
    type = 'income';
  } else if (rawType.includes('transfer')) {
    type = 'transfer';
  } else if (['investment', 'invest', 'gold', 'stocks', 'mutual'].some(k => rawType.includes(k))) {
    type = 'investment';
  } else {
    type = 'expense';
  }

  const category = tx.Category || 'Other';
  const vendor = tx.Vendor || 'N/A';
  const product = tx.Product || vendor;
  const amount = Number(tx.Amount ?? 0);
  const currency = tx.Currency || 'INR';
  const currencySymbol = tx.currency_symbol || '₹';
  const whatsappNumber = '1104381256';

  // IMMUTABLE GMAIL MESSAGE ID HASH - Immune to LLM naming changes!
  const duplicateKey = `email|${emailId}`;

  return {
    json: {
      is_financial: Boolean(tx.is_financial && amount > 0),
      whatsapp_number: whatsappNumber,
      Month: month,
      Date: date,
      Type: type,
      Category: category,
      Vendor: vendor,
      Product: product,
      Amount: amount,
      Currency: currency,
      currency_symbol: currencySymbol,
      duplicate_key: duplicateKey,
      source: 'email',
      from_email: emailData.from?.value?.[0]?.address || emailData.from?.text || 'saurabh7596@gmail.com',
      email_subject: emailData.subject || '',
      email_id: emailId
    }
  };
});

// Combine the transaction data with the database duplicate check result cleanly!
const dbResults = $input.all();
const txItems = $('Filter Valid Transactions').all();

const newItems = [];
for (let i = 0; i < txItems.length; i++) {
  const tx = txItems[i].json;
  const dbRes = dbResults[i]?.json || {};

  // If NO row was found in Postgres, dbRes.id is undefined/null -> Brand New!
  if (!dbRes.id) {
    newItems.push({ json: tx });
  } else {
    console.log(`Skipping duplicate email transaction: ${tx.duplicate_key} (${tx.Vendor} - ${tx.Amount})`);
  }
}

return newItems;

